    requireThat(attachmentPair||action!=='authority-attachment'&&pending.length===1||action==='decision-receive'&&pending.length===0&&set.store.get(tenant,'decision-receipt',result.id)?.decisionId===value.decisionId,'academic_record','Bu akademik işlem eksiksiz değişmez kayıt üretmeli.',503);
    const storedResult={...result};if(action==='authority-download')delete storedResult.file;
    // Semantic append order derives from immutable tenant rows, never an independently mutable sequence.
    for(const r of pending)await tx.query('INSERT INTO public.myys_academic_records (position,tenant,kind,id,unit,owner,data) SELECT coalesce(max(position),0)+1,$1,$2,$3,$4,$5,$6::jsonb FROM public.myys_academic_records WHERE tenant=$1',[tenant,r.kind,r.data.id,r.data.unit,r.data.owner,JSON.stringify(r.data)]);
    // PostgreSQL JSONB text can be larger than compact JSON; check the stored
    // representation before committing an upload that could lock later reads.
    const storedSize=(await tx.query('SELECT count(*) AS rows,coalesce(sum(octet_length(data::text)),0) AS bytes FROM public.myys_academic_records WHERE tenant=$1',[tenant])).rows[0];
    requireThat(Number(storedSize.rows)<=maxRows&&Number(storedSize.bytes)<=maxBytes,'academic_capacity','Bu yerel akademik veri dilimi işlem sınırını aşıyor.',503);
    await tx.query('INSERT INTO public.myys_academic_commands (tenant,person_id,id,action,digest,result) VALUES ($1,$2,$3,$4,$5,$6::jsonb)',[tenant,actor.id,commandId,action,digest,JSON.stringify(storedResult)]);
    await tx.query('INSERT INTO public.myys_academic_audit (tenant,actor,action,record_id,recorded_at) VALUES ($1,$2,$3,$4,$5)',[tenant,actor.id,action,result.id,now]);
    requireThat(this.#now()>=now,'academic_clock','Akademik işlem zamanı geri döndü.',503);return copy(result);
   }finally{set.close();}
  });
 }
 async publicTrust({sessionHash,tenant,unit,permit}){
  local();requireThat(field(tenant,80)&&field(unit),'command','Kurum ve birim gerekli.');
  return this.#identity.withPrincipal({sessionHash,permit,purpose:'academic-write'},async(tx,actor)=>{
   requireThat(actor.tenant===tenant,'not_found','Bu kurum kaydına erişilemiyor.',404);const set=await this.#snapshot(tx,actor);
   try{return publicTrustForPrincipal(set.store,actor,unit,this.#now());}finally{set.close();}
  });
 }
 async programPackage({sessionHash,tenant,programId,permit}){
  local();requireThat(field(tenant,80)&&field(programId),'command','Kurum ve program sürümü gerekli.');
  return this.#identity.withPrincipal({sessionHash,permit,purpose:'academic-write'},async(tx,actor)=>{
   requireThat(actor.tenant===tenant,'not_found','Bu kurum kaydına erişilemiyor.',404);const set=await this.#snapshot(tx,actor);
   try{return programPackageForPrincipal(set.store,actor,programId,this.#now());}finally{set.close();}
  });
 }
 async view({sessionHash,tenant,permit}){
  local();requireThat(field(tenant,80),'command','Kurum kapsamı gerekli.');return this.#identity.withPrincipal({sessionHash,permit,purpose:'academic-read'},async(tx,actor)=>{
   requireThat(actor.tenant===tenant,'not_found','Bu kurum kaydına erişilemiyor.',404);const set=await this.#snapshot(tx,actor);try{const now=this.#now(),core=new MyysCore(set.store,{clock:()=>now}),view=core.academicView(actor),adminUnits=new Set(actor.mfa?actor.memberships.filter(m=>m.roles.includes('admin')).map(m=>m.unit):[]),registry=set.list(actor.tenant,'registry').filter(r=>adminUnits.has(r.unit)),registryIds=new Set(registry.map(r=>r.id));return {...view,trustExportUnits:actor.mfa?actor.memberships.filter(m=>m.roles.some(r=>['it','admin'].includes(r))).map(m=>m.unit):[],keys:keyView(set.store,actor),authority:authorityView(set.store,actor,now),credentialProfiles:profileView(set.store,actor,now),registry,registryReviews:set.list(actor.tenant,'registry-review').filter(r=>registryIds.has(r.recordId)&&adminUnits.has(r.unit)),mode:'isolated-sql-acceptance',official:false,personId:actor.id,sessionExpires:actor.expires,memberships:copy(actor.memberships),supportedActions:[...academicSqlActions],appealPolicies:appealPolicyView(set.store,actor),issuances:core.issuanceView(actor).map(r=>({...r,canSign:false})),signerAvailable:false,supportedTabs:[...(actor.memberships.some(m=>m.roles.some(r=>['it','admin','studentAffairs','quality'].includes(r)))?['keys']:[]),...(actor.memberships.some(m=>m.roles.some(r=>['learner','coordinator','instructor','commission','quality','studentAffairs'].includes(r)))?['issuances']:[]),...(actor.memberships.some(m=>m.roles.some(r=>['admin','commission','studentAffairs'].includes(r)))?['credentialProfiles']:[]),...(adminUnits.size?['registry']:[]),...(actor.memberships.some(m=>m.roles.some(r=>['admin','commission','quality'].includes(r)))?['appealPolicies']:[]),'programs','enrollments','evidence','assessments','decisions','appeals'],scope:'same-sql-identity-academic-transaction'};}finally{set.close();}
