 const h=await sqlAcademicHttp(t),x=await ready(h);for(const who of ['student','admin','issuer'])assert.equal((await h.export(who,x.p.id)).status,404);const r=await h.post('issuer','islem',{tenant:'gazi',commandId:'no-real-issue',action:'issue',input:{programId:x.p.id}});assert.equal(r.status,404);assert.equal((await h.post('issuer','imzala',{tenant:'gazi',issuanceId:'none'})).status,404);
});

