import React,{useState} from 'react';
import {Card,CardHead,Field,Button,Notice,Pill} from './ui.jsx';
const states={pending:'İnceleme bekliyor',rejected:'Uygun bulunmadı',active:'İmzalamaya açık',retired:'Yeni imzaya kapalı · Eski imzalar korunur',compromised:'Ele geçirilmiş · Doğrulama kapalı'};
export function KeyWorkspace({data,busy,command,publishStatus,downloadTrust}){
 const [query,setQuery]=useState(''),[error,setError]=useState('');
 const units=data.memberships.filter(m=>m.roles.includes('it')).map(m=>m.unit),keys=data.keys||[],filtered=keys.filter(k=>(k.jwk.kid+' '+k.unit+' '+k.fingerprint).toLocaleLowerCase('tr').includes(query.toLocaleLowerCase('tr'))),sqlWithoutSigner=!!data.supportedActions&&!data.signerAvailable;
 return <><Notice>Bu sicil yalnız yerel kabul içindir. Açık anahtar kaydı kurumsal belge yetkisi vermez. Özel anahtar bu forma girilmez. Ele geçirilme kaydı akademik notu değiştirmez; güvenilir belge yeniden hazırlanana kadar doğrulamayı kapatır.</Notice>
 {sqlWithoutSigner&&<Notice>Bu denemede yalnız açık anahtar sicili ve insan incelemesi bağlıdır. İmzalama, durum listesi ve bağımsız doğrulama hizmetleri henüz açık değildir.</Notice>}
 {(data.statusLists||[]).map(r=><Card key={r.unit}><CardHead title="İmzalı durum listeleri" sub={r.unit}/><div className="academic-body form-stack"><p>{r.allocationCount} belge için ayrı iptal ve askı listeleri.</p><Pill tone={r.current?'green':'amber'}>{r.current?'Durum listeleri güncel':'Durum listesi yenilenmeli'}</Pill>{r.validUntil&&<p>Geçerlilik sonu: {new Date(r.validUntil).toLocaleString('tr-TR')}</p>}{r.canPublish&&<Button disabled={busy||!data.signerAvailable} onClick={()=>publishStatus(r.unit)}>Durum listelerini güncelle</Button>}{r.canExportTrust&&<Button disabled={busy} onClick={()=>downloadTrust(r.unit)}>Açık güven sicilini indir</Button>}<p>Bu listeler yerel dosya doğrulamasında kullanılır. Kamuya açık kurum durum hizmeti değildir. İptal kalıcıdır; itirazın askı durumu yeniden incelenebilir. Güven sicili yalnız açık anahtar içerir ve bağımsız doğrulayıcıya ayrı, güvenilir kanaldan verilmelidir.</p></div></Card>)}
 {units.length>0&&<Card><CardHead title="Açık imza anahtarı kaydet" sub="Bilgi işlem hazırlar; ayrı yönetici inceler."/><form className="academic-body form-stack" onSubmit={async e=>{e.preventDefault();setError('');const f=new FormData(e.currentTarget);let publicJwk;try{publicJwk=JSON.parse(f.get('jwk'));}catch{setError('Açık anahtar geçerli JSON biçiminde olmalı.');return;}await command('key-register',{unit:f.get('unit'),mode:'local-acceptance',issuer:'https://local-acceptance.invalid/api/rozet/kurum',publicJwk,reason:f.get('reason'),custodyReference:f.get('custody'),replacesId:f.get('previous')||null});}}>
 <Field label="Anahtarın birimi"><select aria-label="Anahtarın birimi" name="unit">{units.map(u=><option key={u}>{u}</option>)}</select></Field>
 <Field label="Açık anahtar (JWK)"><textarea aria-label="Açık anahtar (JWK)" name="jwk" required maxLength={4000} rows={6}/></Field>
 <Field label="Önceki anahtar"><select aria-label="Önceki anahtar" name="previous"><option value="">İlk anahtar · Bağlantı yok</option>{keys.filter(k=>k.review?.outcome==='accepted').map(k=><option key={k.id} value={k.id}>{k.jwk.kid.split('#')[1]}</option>)}</select></Field>
 <Field label="Anahtar sorumluluğu dayanağı"><textarea aria-label="Anahtar sorumluluğu dayanağı" name="custody" required minLength={20} maxLength={2000}/></Field><Field label="Anahtar hazırlama gerekçesi"><textarea aria-label="Anahtar hazırlama gerekçesi" name="reason" required minLength={20} maxLength={2000}/></Field>{error&&<p role="alert">{error}</p>}<Button type="submit" disabled={busy}>Açık anahtarı kaydet</Button></form></Card>}
 <Card><CardHead title="Anahtar ve belge durumu" sub="İnceleme, rotasyon ve güvenlik olayları silinmeden izlenir."/><div className="academic-body form-stack"><Field label="Anahtar ara"><input aria-label="Anahtar ara" value={query} onChange={e=>setQuery(e.target.value)}/></Field>{filtered.map(k=><article key={k.id} className="academic-record key-record"><h3>{k.jwk.kid.split('#')[1]}</h3><Pill tone={k.state==='active'?'green':'amber'}>{sqlWithoutSigner&&k.state==='active'?'Yerel anahtar incelemesi uygun · İmzalama bağlı değil':states[k.state]}</Pill><p>Birim: {k.unit}</p><p>Anahtar özeti: <code>{k.fingerprint}</code></p><p>{k.reason}</p>{k.replacesId&&<p>Rotasyon bağlantısı: {keys.find(x=>x.id===k.replacesId)?.jwk.kid.split('#')[1]||k.replacesId}</p>}<details><summary>Açık anahtarı ve geçmişi incele</summary><pre style={{whiteSpace:'pre-wrap',overflowWrap:'anywhere'}}>{JSON.stringify(k.jwk,null,2)}</pre>{k.review&&<p>Yönetici incelemesi: {k.review.createdBy} · {k.review.createdAt} · {k.review.reason}</p>}{k.changes.map(c=><p key={c.id}>{states[c.state]} · {c.createdAt} · {c.reason} · {c.incidentReference}</p>)}</details>
 {k.canReview&&<form className="form-stack" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);command('key-review',{keyId:k.id,outcome:f.get('outcome'),reason:f.get('reason')});}}><Field label="Anahtar inceleme sonucu"><select aria-label="Anahtar inceleme sonucu" name="outcome"><option value="accepted">Yerel kullanım için uygun</option><option value="rejected">Uygun değil</option></select></Field><Field label="Anahtar inceleme gerekçesi"><textarea aria-label="Anahtar inceleme gerekçesi" name="reason" minLength={20} maxLength={2000} required/></Field><Button type="submit" disabled={busy}>Anahtar incelemesini kaydet</Button></form>}
 {k.canChange&&<details><summary>Anahtar kullanımını değiştir</summary><form className="form-stack" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);command('key-state',{keyId:k.id,expectedState:k.state,state:f.get('state'),reason:f.get('reason'),incidentReference:f.get('incident')});}}><Field label="Yeni anahtar durumu"><select aria-label="Yeni anahtar durumu" name="state">{k.state==='active'&&<option value="retired">Emekliye ayır · Eski imzaları koru</option>}<option value="compromised">Ele geçirilmiş · Tüm imzaları kapat</option></select></Field><Field label="Anahtar değişikliği gerekçesi"><textarea aria-label="Anahtar değişikliği gerekçesi" name="reason" required minLength={20} maxLength={2000}/></Field><Field label="Rotasyon veya olay dayanağı"><textarea aria-label="Rotasyon veya olay dayanağı" name="incident" required minLength={20} maxLength={2000}/></Field><p>Ele geçirilmiş anahtar yeniden etkinleştirilemez. Yeni anahtar ayrı kayıt ve inceleme gerektirir.</p><Button type="submit" disabled={busy}>Anahtar durumunu kaydet</Button></form></details>}</article>)}{!keys.length&&<p>Bu kapsamda anahtar kaydı bulunmuyor.</p>}{!!keys.length&&!filtered.length&&<p>Aramanızla eşleşen anahtar bulunamadı.</p>}</div></Card></>;
}

